/** Actual native whole sources and the original native entry lock. No manual generation permission is created. */
class ReportSupplementWriterAdmissionTest {
 boolean mysql(){return false;}
 DailyReportSupplementInputTest h;ReportInputCaptureService inputs;ReportInputWriterAdmissionService admission;ReportInputWriterAdmissionService.Captured captured;
 void setup()throws Exception{h=new DailyReportSupplementInputTest(){@Override boolean mysql(){return ReportSupplementWriterAdmissionTest.this.mysql();}};h.setup();var base=h.h.data.nativeData().fixture().f();inputs=new ReportInputCaptureService(h.h.service,mock(ReportPeriodInputComponentService.class),base.tx);admission=new ReportInputWriterAdmissionService(base.source,base.tx,inputs);captured=admission.captureSupplement(new ReportInputCaptureService.Scope("report:daily:"+h.day,2,Stage.DAILY_REPORT,h.day),h.cutoff);}
 Prepare command(ReportInputWriterAdmissionService.Captured value,boolean supplement){var scope=value.scope();return new Prepare(scope.logicalKey(),scope.generation(),scope.stage(),scope.day(),null,value.dependencies(),List.of(),value.sourceProof().verifiedDependencyIds(),supplement,"a".repeat(64));}
 @Test void ActualDailyAdmissionRetainsNativeEntryAndRestoresTheOriginalWritableConnection()throws Exception{setup();var base=h.h.data.nativeData().fixture().f();var original=base.writes.execute(base.action("fictional-supplement-daily-writer"),k->null,a->{var connection=DataSourceUtils.getConnection(base.source);var proof=admission.asWriterSource(captured).snapshot(command(captured,true),h.cutoff);assertSame(connection,DataSourceUtils.getConnection(base.source));assertFalse(TransactionSynchronizationManager.isCurrentTransactionReadOnly());assertEquals(TransactionDefinition.ISOLATION_READ_COMMITTED,TransactionSynchronizationManager.getCurrentTransactionIsolationLevel());return proof;});assertTrue(original.complete());assertEquals(1,original.candidates().size());assertEquals(2,base.sends);}
 @Test void ActualPeriodClosureAndCompleteOriginalBodyFreezeInsideTheSameNativeWriter(){var legacy=new ReportInputWriterAdmissionTest(){@Override boolean mysql(){return ReportSupplementWriterAdmissionTest.this.mysql();}};var period=legacy.period();var base=period.f.h.h.f;var inputs=new ReportInputCaptureService(mock(DailyReportInputComponentService.class),period.service,base.tx);var admission=new ReportInputWriterAdmissionService(base.source,base.tx,inputs);Instant cutoff=ReportPeriodInputComponentTest.CUTOFF.plusSeconds(3).plusNanos(1000);var scope=new ReportInputCaptureService.Scope("report:weekly:"+ReportPeriodInputComponentTest.LAST,2,Stage.WEEKLY_REPORT,ReportPeriodInputComponentTest.LAST);var value=admission.captureSupplement(scope,cutoff);var frozen=base.writes.execute(base.action("fictional-supplement-period-writer"),k->null,a->new ReportInputSnapshotService(admission.asWriterSource(value)).freeze(command(value,true),cutoff));assertTrue(frozen.hasContent());assertEquals("partial",frozen.coverageState());assertEquals(6,value.sourceProof().missingInputs().size());assertEquals(1,base.sends);}
 @Test void WrongModeScopeDependenciesIssuerAndTransactionCannotMintWriterAuthority()throws Exception{setup();var base=h.h.data.nativeData().fixture().f();assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-supplement-wrong-mode"),k->null,a->admission.asWriterSource(captured).snapshot(command(captured,false),h.cutoff)));assertThrows(RuntimeException.class,()->new ReportInputWriterAdmissionService(base.source,base.tx,inputs).asWriterSource(captured));assertThrows(RuntimeException.class,()->admission.asWriterSource(captured).snapshot(command(captured,true),h.cutoff));assertThrows(RuntimeException.class,()->h.h.rr(()->admission.asWriterSource(captured).snapshot(command(captured,true),h.cutoff)));assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-supplement-wrong-deps"),k->null,a->admission.asWriterSource(captured).snapshot(new Prepare(captured.scope().logicalKey(),2,Stage.DAILY_REPORT,h.day,null,List.of(),List.of(),List.of(),true,"a".repeat(64)),h.cutoff)));assertThrows(RuntimeException.class,()->h.h.rr(()->admission.captureSupplement(captured.scope(),h.cutoff)));var tx=new TransactionTemplate(base.tx);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(RuntimeException.class,()->tx.execute(s->admission.asWriterSource(captured).snapshot(command(captured,true),h.cutoff)));}
 @Test void CurrentNativeProofChangesRollBackBusinessAndUnknownCaptureIsNeverEmptyEvidence()throws Exception{setup();var base=h.h.data.nativeData().fixture().f();long before=base.jdbc.queryForObject("SELECT slot_revision FROM worker_lock",Long.class);base.jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",h.h.data.nativeData().completed().version().contentId());assertThrows(RuntimeException.class,()->base.writes.execute(base.action("fictional-supplement-proof-changed"),k->null,a->{base.jdbc.update("UPDATE worker_lock SET slot_revision=slot_revision+1");return admission.asWriterSource(captured).snapshot(command(captured,true),h.cutoff);}));assertEquals(before,base.jdbc.queryForObject("SELECT slot_revision FROM worker_lock",Long.class));var fresh=admission.captureSupplement(captured.scope(),h.cutoff);var proof=base.writes.execute(base.action("fictional-supplement-fresh-proof"),k->null,a->admission.asWriterSource(fresh).snapshot(command(fresh,true),h.cutoff));assertTrue(proof.candidates().getFirst().evidence().blocked());var source=mock(javax.sql.DataSource.class);var tx=mock(PlatformTransactionManager.class);var inputs=mock(ReportInputCaptureService.class);var cold=new ReportInputWriterAdmissionService(source,tx,inputs);verifyNoInteractions(source,tx,inputs);assertNull(cold.captureSupplement(captured.scope(),h.cutoff));verifyNoInteractions(source,tx);assertThrows(RuntimeException.class,()->cold.asWriterSource(null));}
}
